\documentclass[border=5pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{xcolor}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    width=10cm,
    height=6cm,
    xlabel={年份},
    ylabel={考研人数},
    title={历年考研人数变化趋势},
    x tick label style={rotate=45, anchor=east},
    xtick=data,
    xticklabels={2021年, 2022年, 2023年, 2024年, 2025年, 2026年},
    grid=major,
    grid style={dashed, gray!30},
    legend style={at={(0.5,-0.2)}, anchor=north},
    ymin=300,
    ymax=500,
    ytick={300,350,400,450,500},
    yticklabels={300万,350万,400万,450万,500万}
]

% 绘制绿色折线图
\addplot[
    color=green!70!black,
    mark=*,
    mark size=2pt,
    line width=1.5pt,
    smooth
] coordinates {
    (1, 377)
    (2, 457)
    (3, 474)
    (4, 438)
    (5, 388)
    (6, 343)
};

% 添加数据标签
\addplot[
    nodes near coords,
    only marks,
    point meta=explicit symbolic,
    mark=none,
    text=black,
    font=\small
] coordinates {
    (1, 377) [377万]
    (2, 457) [457万]
    (3, 474) [474万]
    (4, 438) [438万]
    (5, 388) [388万]
    (6, 343) [343万]
};

\legend{考研人数}

\end{axis}
\end{tikzpicture}

\end{document}
